  function text(value,max=255,empty=false){if(typeof value!=='string'||!value.isWellFormed()||value.length>max||/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value)||!empty&&!value.trim())fail();return value;}
