  function entry(value){const withExtras=value?.schemaVersion===2;exact(value,['schemaVersion','id','createdAt','snapshot','attachmentRefs','events','lastEventNo',...(withExtras?['extraRefs']:[])]);if(![1,2].includes(value.schemaVersion)||!Number.isSafeInteger(value.lastEventNo)||value.lastEventNo<0)fail();const out={schemaVersion:value.schemaVersion,id:ident(value.id),createdAt:iso(value.createdAt),snapshot:snapshot(value.snapshot),attachmentRefs:references(value.attachmentRefs),events:[],lastEventNo:value.lastEventNo};if(withExtras){out.extraRefs=array(value.extraRefs,10).map(reference);if(!out.extraRefs.length||out.extraRefs.some(r=>r.kind!=='extra'))fail();}const events=array(value.events,Number.MAX_SAFE_INTEGER);if(events.length!==value.lastEventNo)fail();let prior=out.createdAt;for(let i=0;i<events.length;i++){const e=events[i];exact(e,['eventNo','recordedAt','outcome','note']);if(e.eventNo!==i+1||!['won','lost','cancelled'].includes(e.outcome)||iso(e.recordedAt)<prior)fail();out.events.push({eventNo:e.eventNo,recordedAt:e.recordedAt,outcome:e.outcome,note:text(e.note,2000,true)});prior=e.recordedAt;}return out;}
  function entries(values){const all=array(values,LIMITS.entries).map(entry),ids=new Set();for(const e of all){if(ids.has(e.id))fail();ids.add(e.id);}return all;}
  function records(values){if(values.length>LIMITS.attachments)fail('QUOTE_LEDGER_LIMIT');const all=array(values,LIMITS.attachments).map(attachmentRecord),keys=new Set();let bytes=0,extraBytes=0;for(const r of all){const key=r.kind+':'+r.sha256;if(keys.has(key))fail();keys.add(key);if(r.kind==='extra')extraBytes+=r.attachment.size;else bytes+=r.attachment.size;}if(bytes>LIMITS.attachmentBytes||extraBytes>LIMITS.extraBytes)fail('QUOTE_LEDGER_LIMIT');return all;}
